'use client'

import { FormEvent, useEffect, useState } from 'react'

const API_URL = process.env.NEXT_PUBLIC_API_URL || 'https://shophoaqua.duongnongtung96.workers.dev'

interface Product {
  id: number
  name: string
  price: number
  tag: string | null
  description: string | null
  image_key: string
}

export default function AdminPage() {
  const [token, setToken] = useState('')
  const [products, setProducts] = useState<Product[]>([])
  const [name, setName] = useState('')
  const [price, setPrice] = useState('')
  const [tag, setTag] = useState('')
  const [description, setDescription] = useState('')
  const [image, setImage] = useState<File | null>(null)
  const [loading, setLoading] = useState(false)
  const [message, setMessage] = useState('')

  async function loadProducts() {
    const response = await fetch(`${API_URL}/api/products`)
    const result = await response.json() as { success: boolean; data: Product[] }
    if (result.success) setProducts(result.data)
  }

  useEffect(() => {
    loadProducts().catch(() => setMessage('Không tải được danh sách sản phẩm.'))
  }, [])

  async function addProduct(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const formElement = event.currentTarget
    if (!image) {
      setMessage('Vui lòng chọn ảnh sản phẩm.')
      return
    }

    setLoading(true)
    setMessage('')
    const form = new FormData()
    form.set('name', name)
    form.set('price', price)
    form.set('tag', tag)
    form.set('description', description)
    form.set('image', image)

    try {
      const response = await fetch(`${API_URL}/api/products`, {
        method: 'POST',
        headers: { 'X-Admin-Token': token },
        body: form,
      })
      const result = await response.json() as { success: boolean; error?: string }
      if (!response.ok || !result.success) throw new Error(result.error || 'Không thể thêm sản phẩm.')

      setName('')
      setPrice('')
      setTag('')
      setDescription('')
      setImage(null)
      formElement.reset()
      await loadProducts()
      setMessage('Đã đăng sản phẩm lên cửa hàng.')
    } catch (error) {
      setMessage(error instanceof Error ? error.message : 'Có lỗi xảy ra khi đăng sản phẩm.')
    } finally {
      setLoading(false)
    }
  }

  const inputStyle = {
    width: '100%',
    padding: '11px 12px',
    border: '1px solid #cbd5d1',
    borderRadius: '5px',
    font: 'inherit',
  }
  const labelStyle = { display: 'grid', gap: '7px', color: '#263831', fontSize: '14px' }

  return (
    <main style={{ maxWidth: '1080px', margin: '0 auto', padding: '32px 20px', color: '#183c2c' }}>
      <a href="/" style={{ color: '#28724b', textDecoration: 'none' }}>← Về cửa hàng</a>
      <header style={{ margin: '24px 0 30px' }}>
        <p style={{ margin: 0, color: '#638071', fontSize: '13px', textTransform: 'uppercase' }}>Fruitica · Quản trị</p>
        <h1 style={{ margin: '8px 0', fontSize: '32px' }}>Sản phẩm</h1>
        <p style={{ margin: 0, color: '#638071' }}>Thêm hoa quả và ảnh mới vào cửa hàng.</p>
      </header>

      <section style={{ display: 'grid', gridTemplateColumns: 'minmax(0, 1fr) minmax(280px, 0.8fr)', gap: '36px' }}>
        <form onSubmit={addProduct} style={{ display: 'grid', alignContent: 'start', gap: '17px' }}>
          <label style={labelStyle}>Mã quản trị
            <input type="password" value={token} onChange={(event) => setToken(event.target.value)} required autoComplete="current-password" style={inputStyle} />
          </label>
          <label style={labelStyle}>Tên hoa quả
            <input value={name} onChange={(event) => setName(event.target.value)} required maxLength={120} style={inputStyle} />
          </label>
          <label style={labelStyle}>Giá (VNĐ)
            <input type="number" min="1" step="1000" value={price} onChange={(event) => setPrice(event.target.value)} required style={inputStyle} />
          </label>
          <label style={labelStyle}>Nhãn sản phẩm
            <input value={tag} onChange={(event) => setTag(event.target.value)} maxLength={40} placeholder="Ví dụ: Mới, Bán chạy" style={inputStyle} />
          </label>
          <label style={labelStyle}>Mô tả
            <textarea value={description} onChange={(event) => setDescription(event.target.value)} rows={3} maxLength={500} style={{ ...inputStyle, resize: 'vertical' }} />
          </label>
          <label style={labelStyle}>Ảnh sản phẩm (JPG, PNG hoặc WebP, tối đa 5 MB)
            <input type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => setImage(event.target.files?.[0] ?? null)} required style={{ ...inputStyle, padding: '9px' }} />
          </label>
          <button type="submit" disabled={loading} style={{ justifySelf: 'start', padding: '12px 20px', border: 0, borderRadius: '5px', background: '#19734a', color: 'white', font: 'inherit', fontWeight: 700, cursor: loading ? 'wait' : 'pointer' }}>
            {loading ? 'Đang đăng...' : 'Đăng sản phẩm'}
          </button>
          {message && <p role="status" style={{ margin: 0, color: message.startsWith('Đã') ? '#19734a' : '#a33b32' }}>{message}</p>}
        </form>

        <section aria-label="Sản phẩm hiện có" style={{ borderLeft: '1px solid #e0e8e3', paddingLeft: '28px' }}>
          <h2 style={{ margin: '0 0 14px', fontSize: '19px' }}>Đang bán <span style={{ color: '#638071', fontWeight: 400 }}>({products.length})</span></h2>
          <div style={{ display: 'grid', gap: '10px' }}>
            {products.map((product) => (
              <article key={product.id} style={{ display: 'grid', gridTemplateColumns: '64px 1fr', gap: '12px', alignItems: 'center', padding: '9px 0', borderBottom: '1px solid #e8eeea' }}>
                <img src={`${API_URL}/api/images/${encodeURIComponent(product.image_key)}`} alt="" style={{ width: '64px', height: '58px', objectFit: 'cover', borderRadius: '4px', background: '#eef4ef' }} />
                <div>
                  <strong>{product.name}</strong>
                  <div style={{ marginTop: '4px', color: '#638071', fontSize: '14px' }}>{product.price.toLocaleString('vi-VN')} đ</div>
                </div>
              </article>
            ))}
            {products.length === 0 && <p style={{ color: '#638071' }}>Chưa có sản phẩm.</p>}
          </div>
        </section>
      </section>

      <style>{`@media (max-width: 700px) { main > section { grid-template-columns: 1fr !important; } main > section > section { border-left: 0 !important; border-top: 1px solid #e0e8e3; padding: 22px 0 0 !important; } }`}</style>
    </main>
  )
}